use tauri::Manager;

// Generated by scripts/third-party-notices.ts and bundled through tauri.conf.json resources.
const NOTICES_RESOURCE: &str = "bin/THIRD_PARTY_NOTICES.txt";

#[tauri::command]
pub fn open_third_party_notices(app: tauri::AppHandle) -> Result<(), String> {
    let path = app
        .path()
        .resolve(NOTICES_RESOURCE, tauri::path::BaseDirectory::Resource)
        .map_err(|e| format!("failed resolving third-party notices: {e}"))?;
    if !path.exists() {
        return Err(format!("third-party notices missing: {}", path.display()));
    }
    crate::open_path_with_default_app(&path)
}
